"use client";

import { useRef, type ReactNode } from "react";
import { motion, useMotionValue, useReducedMotion, useSpring } from "framer-motion";

const RADIUS = 90;
const STRENGTH = 0.4;

export function MagneticButton({ children }: { children: ReactNode }) {
  const ref = useRef<HTMLButtonElement>(null);
  const shouldReduceMotion = useReducedMotion();
  const x = useMotionValue(0);
  const y = useMotionValue(0);
  const springX = useSpring(x, { stiffness: 200, damping: 15, mass: 0.3 });
  const springY = useSpring(y, { stiffness: 200, damping: 15, mass: 0.3 });
  const textX = useSpring(x, { stiffness: 200, damping: 18, mass: 0.2 });
  const textY = useSpring(y, { stiffness: 200, damping: 18, mass: 0.2 });

  const handleMouseMove = (e: React.MouseEvent<HTMLButtonElement>) => {
    if (shouldReduceMotion) return;
    const rect = ref.current?.getBoundingClientRect();
    if (!rect) return;
    const centerX = rect.left + rect.width / 2;
    const centerY = rect.top + rect.height / 2;
    const distX = e.clientX - centerX;
    const distY = e.clientY - centerY;
    const distance = Math.hypot(distX, distY);
    if (distance < RADIUS) {
      x.set(distX * STRENGTH);
      y.set(distY * STRENGTH);
    } else {
      x.set(0);
      y.set(0);
    }
  };

  const handleMouseLeave = () => {
    x.set(0);
    y.set(0);
  };

  return (
    <motion.button
      ref={ref}
      onMouseMove={handleMouseMove}
      onMouseLeave={handleMouseLeave}
      style={{ x: springX, y: springY }}
      whileTap={{ scale: 0.94 }}
      className="rounded-full bg-emerald-700 px-6 py-3 text-sm font-medium text-white shadow-[0_8px_24px_-8px_rgba(4,120,87,0.6)] focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-emerald-700 dark:bg-emerald-500 dark:shadow-[0_8px_24px_-8px_rgba(16,185,129,0.55)] dark:focus-visible:outline-emerald-400"
    >
      <motion.span style={{ x: textX, y: textY }} className="inline-block">
        {children}
      </motion.span>
    </motion.button>
  );
}
